CREATE OR REPLACE FUNCTION public.protect_final_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF OLD.status='FINAL' THEN RAISE EXCEPTION 'Final invoices are immutable. Use a credit/debit note.'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $function$
